"""exotic_other_diseases.py – その他エキゾチック動物の一般的な疾患

ミニブタ、アライグマ、スカンク、プレーリードッグ、ワラビーなど
特定分類に含まれないエキゾチックアニマルを対象とした疾患データベースです。
症状から鑑別診断候補を提示する際に使用します。
この情報は教育目的であり、診断は獣医師にご相談ください。
"""

