    {
        "name": "Tetanus (Porcine)",
        "name_ja": "破傷風（豚）",
        "symptoms": {"stiffness", "muscle_spasms", "opisthotonos", "seizures", "difficulty_eating", "hypersensitivity"},
        "description": "Tetanus (Porcine) is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "破傷風菌毒素による進行性の筋硬直と痙攣。創傷の汚染から発症する。",
        "urgency": "emergency",
        "recommended_tests": ["身体検査", "創傷検査", "血液検査"],
        "causes": "Clostridium tetani toxin causing progressive muscle rigidity and spasms, often from wound contamination.",
        "causes_ja": "Exotic Otherにおける破傷風（豚）の原因: 破傷風菌毒素による進行性の筋硬直と痙攣。創傷の汚染から発症する。",
        "pathophysiology": "Clostridium tetani toxin causing progressive muscle rigidity and spasms, often from wound contamination. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "破傷風（豚）はExotic Otherにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "Tetanus antitoxin 1500-3000 IU IM. Metronidazole 10-15 mg/kg PO q12h. Wound debridement. Muscle relaxants (diazepam). Dark, quiet environment. IV fluids.",
        "treatment_ja": "Exotic Otherにおける破傷風（豚）の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "予防には、適切な衛生管理、利用可能なワクチン接種、外傷の早期治療、ストレス軽減、適切な換気、感染動物の隔離が重要である。",
        "prevention_ja": "破傷風（豚）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "予後は重症度、基礎疾患、治療の時期に依存する。早期の積極的介入により転帰が改善する。治療の遅延は予後慎重〜不良となる。",
        "prognosis_ja": "破傷風（豚）の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
