    {
        "name": "Gastrointestinal Stasis",
        "name_ja": "消化管うっ滞",
        "symptoms": {"anorexia", "bloating", "constipation", "lethargy", "teeth_grinding", "abdominal_pain"},
        "description": "Gastrointestinal Stasis is a gastrointestinal condition affecting digestive function and nutrient absorption.",
        "description_ja": "ストレス、疼痛、食事、脱水による消化管運動の低下または停止。",
        "urgency": "high",
        "recommended_tests": ["腹部X線検査", "身体検査", "血液検査"],
        "causes": "Reduced or absent GI motility from stress, pain, diet, or dehydration; common across exotic mammals.",
        "causes_ja": "Exotic Otherにおける消化管うっ滞の原因: ストレス、疼痛、食事、脱水による消化管運動の低下または停止。",
        "pathophysiology": "Gastrointestinal Stasis is a nutritional disorder in Exotic Other. Reduced or absent GI motility from stress, pain, diet, or dehydration; common across exotic mammals. The condition results from inadequate intake, malabsorption, or excessive supplementation of specific nutrients. Deficiency states impair biochemical pathways dependent on the affected nutrient as cofactor or substrate, leading to cellular dysfunction. Excess states cause toxicity through accumulation in tissues or disruption of nutrient interactions. Species-specific dietary requirements make proper nutritional management critical for prevention.",
        "pathophysiology_ja": "消化管うっ滞はExotic Otherにおける栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Treatment of gastrointestinal stasis in exotic other centers on correcting the nutritional imbalance. Deficiency states require supplementation of the specific nutrient through dietary correction or therapeutic supplementation. Excess states require dietary restriction and supportive care for organ damage. Gradual correction prevents refeeding syndrome in malnourished animals. Species-specific dietary requirements must guide long-term nutritional planning. Regular reassessment ensures adequate without excessive intake.",
        "treatment_ja": "【エキゾチック動物における消化管うっ滞】\n消化管うっ滞はエキゾチック動物における正確な臨床評価（病歴、身体検査、CBC・生化学、画像）から治療方針を決定。\n基礎疾患の特定→特異的治療＋支持療法の組み合わせが原則。\n経過モニタリング: 主訴の改善、検査値の変化、QOLを2-4週毎に再評価。\n複雑症例はエキゾチック動物専門医（ACZMまたはAVMAエキゾチック分科会等）に紹介を検討。\n支持療法: 種に適切な輸液・栄養管理・疼痛緩和を行う。\n【鑑別と経過観察】類似症候を呈する疾患の除外と、治療4-8週後の再評価が予後改善の鍵。重症度・併発症によってはエキゾチック動物の専門医紹介を考慮する。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "消化管うっ滞の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "予後は疾患の重症度、治療介入の時期、治療への反応に依存する。早期診断と適切な治療により転帰が改善する。",
        "prognosis_ja": "消化管うっ滞の予後: 急性は多くが良好。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Gastric Dilatation",
        "name_ja": "胃拡張",
        "symptoms": {"bloating", "dyspnea", "abdominal_pain", "lethargy", "sudden_death"},
        "description": "Gastric Dilatation is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "ガスや液体による急性胃拡張。生命を脅かす可能性がある。",
        "urgency": "emergency",
        "recommended_tests": ["腹部X線検査", "身体検査", "血液ガス分析"],
        "causes": "Acute gastric distension from gas or fluid accumulation, potentially life-threatening. Often associated with dietary indiscretion or aerophagia.",
        "causes_ja": "Exotic Otherにおける胃拡張の原因: ガスや液体による急性胃拡張。生命を脅かす可能性がある。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "胃拡張はExotic Otherにおける消化器疾患である。粘膜の完全性、運動性、分泌機能、またはマイクロバイオームバランスの障害を伴う。炎症により上皮バリアが損傷し、吸収不良、体液喪失、細菌トランスロケーションの可能性がある。運動障害（低運動性/うっ滞または亢進）により通過時間と消化効率が変化する。後腸発酵動物では盲腸/結腸フローラの破壊が致死的ディスバイオーシスと腸管毒素症を引き起こしうる。",
        "treatment": "Orogastric tube decompression under sedation. SC/IV fluids. R/O GDV, foreign body. Radiographs. Metoclopramide 0.5 mg/kg SC q8h.",
        "treatment_ja": "【緊急処置】生命を脅かす緊急疾患（特にウサギ・モルモット・ハムスター・ミニピグ）。心血管虚脱・呼吸困難・ショック対応を最優先。【診断】身体検査で腹部膨満（ピンポン球様硬度・タンパン音）、頻脈、頻呼吸、ショック徴候。腹部X線（背腹・側面）で胃のガス充満、捻転（GDV）の場合は『ダブルバブル』『コンパートメント化』所見。腹部超音波で胃容量・捻転評価、胃壁血流ドップラー（虚血評価）。血液ガス分析（代謝性アシドーシス、乳酸上昇>5 mmol/Lで虚血示唆）、CBC・生化学（脱水、低K、低タンパク、肝酵素上昇）。【緊急治療プロトコル】(1) 静脈ライン確保、IV結晶液（リンゲル液10-20 mL/kg ボーラス、ショック時60-90 mL/kg/時）、(2) 経口胃管挿入で減圧（咽頭から胃まで、軽度鎮静下: ミダゾラム0.2-0.5 mg/kg IM＋ブトルファノール0.2-0.5 mg/kg IM）、(3) 減圧成功時は温水（10-20 mL/kg）注入し胃洗浄、ガス・液体除去、(4) 経胃管挿入失敗時は経皮的胃穿刺（カテーテル24G、左側肋骨部、X線/超音波ガイド下）、(5) 整腸薬: シメチコン65-130 mg PO（消泡剤）、(6) 制吐薬: マロピタント1 mg/kg SC q24h、メトクロプラミド0.5-1 mg/kg SC q6-8h、(7) 鎮痛: ブプレノルフィン0.01-0.05 mg/kg SC q6-8h、メロキシカム0.3-0.6 mg/kg SC q24h（ウサギ）。【外科適応】胃捻転（GDV）確認、保存療法無効、胃壁壊死/穿孔疑い: 緊急開腹術。胃整復、胃壁評価、必要に応じて部分胃切除、胃固定術（ウサギでの報告あり）。麻酔: イソフルラン+IPPV、循環モニター強化、体温管理。【支持療法】IV輸液継続（25-50 mL/kg/日）、強制給餌（Critical Care草食動物用 10-15 mL/kg q4-6h、回復後）、加温（28-30℃ホスピタル）、プロバイオティクス、ビタミンB群。【再発予防】食事管理（高繊維、ペレット制限、糖分・穀物回避）、急速給餌回避、ストレス軽減、運動促進、嫌気性腸内環境改善（牧草中心）。【予後】早期発見・治療で50-70%、GDV合併や12時間以上経過例で20-30%以下。【参考文献】Quesenberry KE, Carpenter JW. Ferrets, Rabbits, and Rodents 4th ed (2021); Carpenter JW. Exotic Animal Formulary 6th ed (2022); Harcourt-Brown FM. Textbook of Rabbit Medicine 2nd ed (2020); Mitchell MA, Tully TN. Manual of Exotic Pet Practice (2009); J Exot Pet Med - exotic GI emergencies.",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "胃拡張の予防: 食事管理。異物誤食予防。",
        "prognosis": "予後は重症度、基礎疾患、治療の時期に依存する。早期の積極的介入により転帰が改善する。治療の遅延は予後慎重〜不良となる。",
        "prognosis_ja": "胃拡張の予後: 急性は多くが良好。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Enteritis / Colitis (Exotic Mammal)",
        "name_ja": "腸炎・大腸炎（エキゾチック哺乳類）",
        "symptoms": {"diarrhea", "bloody_stool", "anorexia", "dehydration", "lethargy", "abdominal_pain"},
        "description": "Enteritis / Colitis (Exotic Mammal) is a gastrointestinal condition affecting digestive function and nutrient absorption.",
        "description_ja": "感染、食事の問題、ストレスによる腸管の炎症。",
        "urgency": "high",
        "recommended_tests": ["糞便検査", "糞便培養", "血液検査", "腹部X線検査"],
        "causes": "Inflammation of the intestinal tract caused by bacterial, viral, or parasitic infection, dietary changes, stress, or toxin ingestion.",
        "causes_ja": "Exotic Otherにおける腸炎・大腸炎（エキゾチック哺乳類）の原因: 感染、食事の問題、ストレスによる腸管の炎症。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "腸炎・大腸炎（エキゾチック哺乳類）はExotic Otherにおける消化器疾患である。粘膜の完全性、運動性、分泌機能、またはマイクロバイオームバランスの障害を伴う。炎症により上皮バリアが損傷し、吸収不良、体液喪失、細菌トランスロケーションの可能性がある。運動障害（低運動性/うっ滞または亢進）により通過時間と消化効率が変化する。後腸発酵動物では盲腸/結腸フローラの破壊が致死的ディスバイオーシスと腸管毒素症を引き起こしうる。",
        "treatment": "Enrofloxacin 5-10 mg/kg PO q12h + Metronidazole 15-20 mg/kg PO q12h x 10-14d. SC fluids. Syringe feed. Probiotic.",
        "treatment_ja": "【診断】糞便検査（直接塗抹・浮遊法・抗酸染色）でCryptosporidium、Coccidia、Giardia、線虫卵を確認。糞便培養（Salmonella、E. coli enterotoxigenic、Clostridium difficile/perfringens、Yersinia）+ 感受性試験。Clostridium difficile毒素A/B検出（PCR/ELISA）。種別重要病原体: ウサギ→Lawsonia、Eimeria、ロタウイルス、フェレット→Helicobacter mustelae、ECE coronavirus、Lawsonia、モルモット→Tyzzer's disease（Clostridium piliforme）、ハムスター→proliferative ileitis（Lawsonia）。CBC・生化学（脱水、低K、低タンパク、低アルブミン）。腹部X線（イレウス、腸ガス、巨大結腸）、超音波（腸壁肥厚、腸間膜リンパ節）。【治療】病原体特異的治療を優先。一般的初期治療: エンロフロキサシン5-10 mg/kg PO/SC q12h × 7-14日（ウサギは10-15 mg/kg、Pseudomonas/E. coli）+ メトロニダゾール15-20 mg/kg PO q12h × 10-14日（嫌気性菌・Giardia・Clostridium）。Lawsonia（ハムスター/フェレット増殖性腸炎）: クロラムフェニコール50 mg/kg PO q12h × 14-21日、テトラサイクリン20 mg/kg PO q8h × 14日。Coccidia: トルトラズリル20 mg/kg PO q24h × 3日反復、サルファ剤（スルファジメトキシン25 mg/kg PO q24h × 5-10日）。Giardia: メトロニダゾール（上記）またはフェンベンダゾール20 mg/kg PO q24h × 5日。【種特異的禁忌】ウサギ・モルモット・チンチラ・ハムスターでは経口ペニシリン系・セフェム系・マクロライド系（クリンダマイシン・リンコマイシン含む）禁忌（致死的腸内細菌叢崩壊）。【支持療法】SC/IV輸液（リンゲル液80-100 mL/kg/日、ウサギ）、強制給餌（Critical Care for Herbivores草食動物 50 mL/kg/日 q4-6h、フェレット用Carnivore Care）、温度管理、プロバイオティクス（Bene-Bac、ヒト用Lactobacillus、サッカロマイセス・ボラルディ250-500 mg PO q12h、Clostridium difficile感染時に有効）、コレスチラミン200 mg/kg PO q12h（毒素吸着、Clostridium感染時）、鎮痛（メロキシカム0.3-0.6 mg/kg SC q24h ウサギ、ブプレノルフィン0.01-0.05 mg/kg SC q6-12h）。【再発予防】高繊維食（ウサギ・モルモット: 牧草80%以上）、急な食事変更回避、抗菌薬使用慎重、新規個体30-90日隔離、清潔な飲水、ストレス軽減、定期検便。【参考文献】Quesenberry KE, Carpenter JW. Ferrets, Rabbits, and Rodents 4th ed (2021); Carpenter JW. Exotic Animal Formulary 6th ed (2022); Harcourt-Brown FM. Textbook of Rabbit Medicine 2nd ed (2020); Donnelly TM. Vet Clin North Am Exot Anim Pract - exotic mammal GI; J Exot Pet Med.",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "腸炎・大腸炎（エキゾチック哺乳類）の予防: 食事管理。異物誤食予防。",
        "prognosis": "予後は疾患の重症度、治療介入の時期、治療への反応に依存する。早期診断と適切な治療により転帰が改善する。",
        "prognosis_ja": "腸炎・大腸炎（エキゾチック哺乳類）の予後: 急性は多くが良好。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
