    {
        "name": "Dental Malocclusion (Exotic Mammal)",
        "name_ja": "不正咬合（エキゾチック哺乳類）",
        "symptoms": {"malocclusion", "overgrown_teeth", "drooling", "difficulty_eating", "weight_loss", "anorexia"},
        "description": "Dental Malocclusion (Exotic Mammal) is a dental condition affecting tooth structure, alignment, or oral health.",
        "description_ja": "歯の不整列または過成長。常生歯を持つ齧歯類やプレーリードッグに多い。",
        "urgency": "moderate",
        "recommended_tests": ["口腔内検査", "頭部X線検査", "CT検査"],
        "causes": "Misalignment or overgrowth of teeth, especially in rodents, lagomorphs, and prairie dogs with continuously growing teeth.",
        "causes_ja": "Exotic Otherにおける不正咬合（エキゾチック哺乳類）の原因: 歯の不整列または過成長。常生歯を持つ齧歯類やプレーリードッグに多い。",
        "pathophysiology": "Dental Malocclusion (Exotic Mammal) is a dental/oral condition in Exotic Other. Misalignment or overgrowth of teeth, especially in rodents, lagomorphs, and prairie dogs with continuously growing teeth. Dental pathology in this species involves disruption of normal tooth structure, alignment, or supporting tissues. Abnormal tooth growth or wear patterns can lead to malocclusion, root elongation, and periapical abscess formation. Periodontal disease involves bacterial biofilm accumulation, gingival inflammation, and progressive loss of periodontal attachment. Pain from dental disease often manifests as reduced food intake, selective eating, weight loss, and ptyalism.",
        "pathophysiology_ja": "不正咬合（エキゾチック哺乳類）はExotic Otherにおける歯科・口腔疾患である。歯の構造、配列、または支持組織の正常な機能が障害される。異常な歯の成長・摩耗パターンは不正咬合、歯根伸長、根尖膿瘍形成を引き起こしうる。歯周病は細菌バイオフィルムの蓄積、歯肉炎症、歯周付着の進行性喪失を伴う。歯科疾患による疼痛は食欲低下、選択的摂食、体重減少、流涎として現れることが多い。",
        "treatment": "Treatment includes dental trimming or filing under anesthesia, pain management, dietary modification to encourage natural wear, and regular dental monitoring.",
        "treatment_ja": "Exotic Otherにおける不正咬合（エキゾチック哺乳類）の治療には鎮静または麻酔下での歯科検査が必要である。不正咬合は種と重症度に応じて歯のトリミング、研磨、抜歯が必要となる。根尖膿瘍には排膿、デブリードマン、全身性抗菌薬が必要である。歯周病治療にはスケーリング、研磨、重度罹患歯の抜歯を含む。種に適した鎮痛薬による疼痛管理が不可欠である。食事の調整により回復を促進し再発を予防する。",
        "prevention": "自然な歯の摩耗を促す適切な高繊維食の提供、定期的な歯科検診、選択的摂食の回避が予防に重要である。",
        "prevention_ja": "不正咬合（エキゾチック哺乳類）の予防には自然な歯の摩耗を促進する適切な咀嚼材と食事、定期的な歯科検査、発生しつつある不正咬合の早期矯正、種に適した食物繊維の提供が含まれる。",
        "prognosis": "Fair to good with regular dental management. Hereditary malocclusion requires lifelong monitoring and periodic correction.",
        "prognosis_ja": "不正咬合（エキゾチック哺乳類）の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "young", "senior"},
    },
