    {
        "name": "External Parasites (Mites/Fleas/Ticks)",
        "name_ja": "外部寄生虫（ダニ・ノミ・マダニ）",
        "symptoms": {"pruritus", "hair_loss", "dermatitis", "skin_crusting", "skin_redness", "lethargy"},
        "description": "External Parasites (Mites/Fleas/Ticks) is a parasitic condition that causes clinical signs ranging from subclinical to severe systemic disease.",
        "description_ja": "外部寄生虫の寄生による皮膚炎、掻痒、疾病伝播のリスク。",
        "urgency": "moderate",
        "recommended_tests": ["皮膚スクレイピング", "顕微鏡検査", "被毛検査"],
        "causes": "Infestation by ectoparasites causing dermatitis, pruritus, and potential disease transmission.",
        "causes_ja": "Exotic Otherにおける外部寄生虫（ダニ・ノミ・マダニ）の原因: 外部寄生虫の寄生による皮膚炎、掻痒、疾病伝播のリスク。",
        "pathophysiology": "External Parasites (Mites/Fleas/Ticks) is a parasitic condition in Exotic Other. Infestation by ectoparasites causing dermatitis, pruritus, and potential disease transmission. The parasite establishes infection through ingestion, percutaneous penetration, or vector-mediated transmission. It exploits host resources for nutrition and reproduction while evading immune defenses through antigenic variation, immunomodulation, or intracellular sequestration. Tissue damage results from direct parasitic feeding, mechanical disruption, toxic metabolic byproducts, and the host's inflammatory and immune responses. Heavy parasite burdens can lead to anemia, malnutrition, organ dysfunction, and secondary infections.",
        "pathophysiology_ja": "外部寄生虫（ダニ・ノミ・マダニ）はExotic Otherにおける寄生虫疾患である。寄生虫は経口摂取、経皮的侵入、またはベクター媒介伝播を通じて感染を確立する。抗原変異、免疫調節、細胞内隔離により宿主の免疫防御を回避しながら、宿主の栄養と資源を利用して増殖する。組織損傷は寄生虫の直接的な摂食、機械的破壊、有毒代謝副産物、宿主の炎症・免疫応答に起因する。重度の寄生虫感染は貧血、栄養失調、臓器機能障害、二次感染を引き起こしうる。",
        "treatment": "Ivermectin 0.2 mg/kg SC (species-appropriate). Selamectin topical. Environmental treatment. Treat all contacts.",
        "treatment_ja": "Exotic Otherにおける外部寄生虫（ダニ・ノミ・マダニ）の治療には、同定された寄生虫に応じた適切な駆虫薬が必要である。一部の駆虫薬は特定の種に有毒であるため、種に適した用量設定が重要である。全てのライフステージを排除するため複数回投与が必要な場合がある。環境消毒と接触動物の治療で再感染を防止する。貧血、脱水、栄養失調などの二次的合併症に対する支持療法を行う。",
        "prevention": "定期的な寄生虫スクリーニングと駆虫、環境衛生、新規動物の検疫、過密飼育の回避が予防に重要である。",
        "prevention_ja": "外部寄生虫（ダニ・ノミ・マダニ）の予防には定期的な予防駆虫、環境衛生と糞便除去、新規動物の隔離・検査、ベクター防除、中間宿主や汚染環境への曝露回避が含まれる。",
        "prognosis": "Good with appropriate antiparasitic treatment. Reinfection is possible without environmental management.",
        "prognosis_ja": "外部寄生虫（ダニ・ノミ・マダニ）の予後: 駆虫薬で良好。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
