    # ── Nutritional ───────────────────────────────────────────────────
    {
        "name": "Vitamin C Deficiency (Scurvy-like)",
        "name_ja": "ビタミンC欠乏症",
        "symptoms": {"weakness", "joint_swelling", "lameness", "hair_loss", "lethargy", "anorexia"},
        "description": "Vitamin C Deficiency (Scurvy-like) is a nutritional or metabolic disorder caused by dietary imbalance or deficiency.",
        "description_ja": "アスコルビン酸欠乏による結合組織・血管機能障害。",
        "urgency": "moderate",
        "recommended_tests": ["血液検査", "食事内容評価"],
        "causes": "Ascorbic acid deficiency causing connective tissue and vascular dysfunction; relevant for guinea pig-like exotics.",
        "causes_ja": "Exotic OtherにおけるビタミンC欠乏症の原因: アスコルビン酸欠乏による結合組織・血管機能障害。",
        "pathophysiology": "Vitamin C Deficiency (Scurvy-like) is a nutritional disorder in Exotic Other. Ascorbic acid deficiency causing connective tissue and vascular dysfunction; relevant for guinea pig-like exotics. The condition results from inadequate intake, malabsorption, or excessive supplementation of specific nutrients. Deficiency states impair biochemical pathways dependent on the affected nutrient as cofactor or substrate, leading to cellular dysfunction. Excess states cause toxicity through accumulation in tissues or disruption of nutrient interactions. Species-specific dietary requirements make proper nutritional management critical for prevention.",
        "pathophysiology_ja": "ビタミンC欠乏症はExotic Otherにおける栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Treatment of vitamin c deficiency (scurvy-like) in exotic other centers on correcting the nutritional imbalance. Deficiency states require supplementation of the specific nutrient through dietary correction or therapeutic supplementation. Excess states require dietary restriction and supportive care for organ damage. Gradual correction prevents refeeding syndrome in malnourished animals. Species-specific dietary requirements must guide long-term nutritional planning. Regular reassessment ensures adequate without excessive intake.",
        "treatment_ja": "【エキゾチック動物におけるビタミンC欠乏症】\nビタミンC欠乏症は栄養素過不足の特定と食事処方の見直しが治療の根幹。検査（血清濃度、骨密度、X線評価）で重症度を確定。\n食事改善が反応得るまで4-8週、補充量は不足量・体重・腎肝機能で個別調整。\n原因の根本（飼育環境、給餌頻度、添加物、UVB照射）を是正しなければ再発する。\nエキゾチック動物に特異的な必要量はQuesenberry & Carpenter (Exotic Animal Medicine for the Veterinary Technician) または Carpenter Exotic Animal Formulary 6th ed を参照。\n支持療法: 種に適切な輸液・栄養管理・疼痛緩和を行う。\n【鑑別と経過観察】類似症候を呈する疾患の除外と、治療4-8週後の再評価が予後改善の鍵。重症度・併発症によってはエキゾチック動物の専門医紹介を考慮する。",
        "prevention": "種に適したバランスの取れた食事（十分なビタミン・ミネラル）の提供、必要に応じた適切なUVB照明、定期的な栄養評価が予防に重要である。",
        "prevention_ja": "ビタミンC欠乏症の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "Good with dietary correction and supplementation. Clinical signs typically improve within weeks of appropriate nutrition. Severe cases may have residual deficits.",
        "prognosis_ja": "ビタミンC欠乏症の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Vitamin A Deficiency (Exotic Mammal)",
        "name_ja": "ビタミンA欠乏症（エキゾチック哺乳類）",
        "symptoms": {"skin_lesions", "eye_discharge", "cloudy_eyes", "anorexia", "weakness"},
        "description": "Vitamin A Deficiency (Exotic Mammal) is a nutritional or metabolic disorder caused by dietary imbalance or deficiency.",
        "description_ja": "ビタミンA不足による上皮化生、眼疾患、免疫抑制。",
        "urgency": "moderate",
        "recommended_tests": ["血液検査", "食事内容評価", "眼科検査"],
        "causes": "Dietary deficiency of vitamin A causing squamous metaplasia of epithelial tissues, ocular disease, and immunosuppression.",
        "causes_ja": "Exotic OtherにおけるビタミンA欠乏症（エキゾチック哺乳類）の原因: ビタミンA不足による上皮化生、眼疾患、免疫抑制。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "ビタミンA欠乏症（エキゾチック哺乳類）はExotic Otherにおける栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Supplement deficient nutrient at species-appropriate dose. Correct diet to balanced commercial formulation. Treat secondary complications. Monitor response.",
        "treatment_ja": "【エキゾチック動物におけるビタミンA欠乏症（エキゾチック哺乳類）】\nビタミンA欠乏症（エキゾチック哺乳類）は栄養素過不足の特定と食事処方の見直しが治療の根幹。検査（血清濃度、骨密度、X線評価）で重症度を確定。\n食事改善が反応得るまで4-8週、補充量は不足量・体重・腎肝機能で個別調整。\n原因の根本（飼育環境、給餌頻度、添加物、UVB照射）を是正しなければ再発する。\nエキゾチック動物に特異的な必要量はQuesenberry & Carpenter (Exotic Animal Medicine for the Veterinary Technician) または Carpenter Exotic Animal Formulary 6th ed を参照。\n支持療法: 種に適切な輸液・栄養管理・疼痛緩和を行う。\n【鑑別と経過観察】類似症候を呈する疾患の除外と、治療4-8週後の再評価が予後改善の鍵。重症度・併発症によってはエキゾチック動物の専門医紹介を考慮する。",
        "prevention": "種に適したバランスの取れた食事（十分なビタミン・ミネラル）の提供、必要に応じた適切なUVB照明、定期的な栄養評価が予防に重要である。",
        "prevention_ja": "ビタミンA欠乏症（エキゾチック哺乳類）の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "Good with dietary correction and supplementation. Clinical signs typically improve within weeks of appropriate nutrition. Severe cases may have residual deficits.",
        "prognosis_ja": "ビタミンA欠乏症（エキゾチック哺乳類）の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
