# Enrich DISEASES with content from diseases_all_species.json
enrich_diseases(DISEASES, "Exotic Other")


def analyze_symptoms(
    symptoms: List[str],
    age_stage: str = "",
    breed: str | None = None,
    *,
    onset: str | None = None,
    age_years: float | None = None,
    species: str | None = None,
    lab_values: dict | None = None,
    gender: str | None = None,
    vaccines=None,
    vaccination_status=None,
) -> Dict[str, Any]:
    """その他エキゾチック動物用の鑑別診断エンジン。

    Args:
        symptoms: ユーザーが報告した症状のリスト
        age_stage: 任意の年齢/ライフステージ情報
        breed: 任意の種名情報

    Returns:
        辞書形式の分析結果
    """
    return analyze_symptoms_generic(
        symptoms,
        DISEASES,
        SYMPTOM_NAMES,
        ADVICE,
        onset=onset,
        age_years=age_years,
        breed=breed,
        species=species,
        lab_values=lab_values,
        gender=gender,
        vaccines=vaccines,
        vaccination_status=vaccination_status,
        prevalence_map=prevalence_data.SPECIES_PREVALENCE.get("exotic_other", {}),
    )
